// AUTO-GENERATED by gen.py (burst=64, outstanding=16). HBM streaming microbenchmark for the Alveo U55C (Vitis HLS 2023.2).
//
// 32 independent 512-bit AXI masters, one per HBM pseudo-channel (PC), each driven by its own
// process inside a DATAFLOW region so all active PCs stream concurrently.
// Runtime arguments (one build covers the whole PC / pattern sweep):
//   mode  0 = read only (XOR-reduce; checksum written to word 4n)
//         1 = write only
//         2 = copy, single pipelined loop (read word i, write word 2n+i); HLS infers no bursts
//         3 = copy, reader->FIFO->writer dataflow (bursted); blk/skip ignored
//   n     words (64 B) per PC per repetition;  blk/skip: access blk words then skip `skip` words
//         (mimics a gate on qubit q, where blk = skip = 2^q/8 words for complex64)
//   reps  repetitions;  mask: bit p enables PC p
// Each enabled PC writes its loop-iteration count (= cycles at II=1) to word 4n+1 of its buffer.
#include <ap_int.h>
#include <hls_stream.h>
typedef ap_uint<512> w512;

// mode 3: bursted copy = reader process -> FIFO -> writer process on the same AXI bundle
static void cp_rd(w512 *p, hls::stream<w512> &s, int n, int reps) {
    for (int r = 0; r < reps; r++)
        for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II = 1
#pragma HLS LOOP_TRIPCOUNT min = 1 max = 4194304
            s.write(p[i]);
        }
}
static void cp_wr(w512 *p, hls::stream<w512> &s, int n, int reps) {
    for (int r = 0; r < reps; r++)
        for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II = 1
#pragma HLS LOOP_TRIPCOUNT min = 1 max = 4194304
            p[2L * n + i] = s.read();
        }
}
static void cp_df(w512 *p, int n, int reps) {
#pragma HLS DATAFLOW
    hls::stream<w512, 64> s;
    cp_rd(p, s, n, reps);
    cp_wr(p, s, n, reps);
}

static void pc_proc(w512 *p, int mode, int n, int blk, int skip, int reps, int en) {
#pragma HLS INLINE off
    if (!en) return;
    w512 acc = 0;
    unsigned long it = 0;
    const int stride = blk + skip;
    const int nblk = (n + blk - 1) / blk;
    // one loop nest per mode so each has a single access pattern (fused version gave II = 140)
    if (mode == 3) { cp_df(p, n, reps); p[4L * n + 1] = (w512)((unsigned long)n * reps); return; }
    if (mode == 0) {
    RD_REP: for (int r = 0; r < reps; r++)
    RD_BLK: for (int b = 0; b < nblk; b++)
    RD_WORD: for (int j = 0; j < blk; j++) {
#pragma HLS PIPELINE II = 1
#pragma HLS LOOP_TRIPCOUNT min = 1 max = 4194304
                it++;
                acc ^= p[(long)b * stride + j];
            }
        p[4L * n] = acc;
    } else if (mode == 1) {
    WR_REP: for (int r = 0; r < reps; r++)
    WR_BLK: for (int b = 0; b < nblk; b++)
    WR_WORD: for (int j = 0; j < blk; j++) {
#pragma HLS PIPELINE II = 1
#pragma HLS LOOP_TRIPCOUNT min = 1 max = 4194304
                it++;
                const long i = (long)b * stride + j;
                p[i] = (w512)(i + r);
            }
    } else {
    CP_REP: for (int r = 0; r < reps; r++)
    CP_BLK: for (int b = 0; b < nblk; b++)
    CP_WORD: for (int j = 0; j < blk; j++) {
#pragma HLS PIPELINE II = 1
#pragma HLS LOOP_TRIPCOUNT min = 1 max = 4194304
#pragma HLS DEPENDENCE variable = p type = inter false
#pragma HLS DEPENDENCE variable = p type = intra false
                it++;
                const long i = (long)b * stride + j;
                p[2L * n + i] = p[i];   // src [0,2n) and dst [2n,4n) never overlap
            }
    }
    p[4L * n + 1] = (w512)it;
}

